     9|class PhoneLink : private juce::Timer {
    10|public:
    11|    enum class State { NoAdb, WaitingForPhone, Connected, SyncError };
    12|
    13|    struct Listener {
    14|        virtual ~Listener() = default;
    15|        virtual void phoneStateChanged(State newState, const juce::String& info) = 0;
    16|        virtual void syncReceived(const juce::var& payload) = 0;
