     7|bool installAdbDriverOnce(const juce::File& driverFolder) {
     8|#ifdef _WIN32
     9|    const auto inf = driverFolder.getChildFile("android_winusb.inf");
    10|    if (!inf.existsAsFile()) return false;
    11|    juce::ChildProcess p;
    12|    // --install permite precargar el paquete firmado por Google; la propia
    13|    // instalación de Windows encola el resto al enchufar el móvil.
    14|    return p.start("pnputil /add-driver \"" + inf.getFullPathName() + "\" /install", 0)
    15|            && p.waitForProcessToFinish(20000)
    16|            && p.getExitCode() == 0;
    17|#else
    18|    juce::ignoreUnused(driverFolder);
    19|    return false;
    20|#endif
    21|}
