    31|juce::String PhoneLink::runAdb(const juce::String& args, int timeoutMs) {
    32|    if (!adb_.existsAsFile()) return {};
    33|    juce::ChildProcess p;
    34|    if (!p.start("\"" + adb_.getFullPathName() + "\" " + args, 0)) return {};
    35|    if (!p.waitForProcessToFinish(static_cast<unsigned>(timeoutMs))) { p.kill(); return {}; }
    36|    return p.readAllProcessOutput().trim();
    37|}
