    39|void PhoneLink::timerCallback() { pollDevices(); }
    40|
    41|void PhoneLink::pollDevices() {
    42|    if (!adb_.existsAsFile()) {
    43|        if (state_.load() != State::NoAdb) {
    44|            state_.store(State::NoAdb);
    45|            lastInfo_ = "adb no encontrado";
    46|        }
    47|        return;
    48|    }
    49|
    50|    const auto out = runAdb("devices -l");
    51|    // Salida esperada: "List of devices attached\nSERIAL\tdevice ..."
    52|    juce::String serial;
    53|    for (const auto& line : juce::StringArray::fromLines(out)) {
    54|        const auto t = line.trim();
    55|        if (t.isNotEmpty() && t.containsChar('\t') && t.endsWith("device")) {
    56|            serial = t.upToFirstOccurrenceOf("\t", false, false);
    57|            break;
    58|        }
    59|    }
    60|
    61|    if (serial.isEmpty()) {
    62|        deviceSerial_ = {};
    63|        state_.store(State::WaitingForPhone);
    64|        lastInfo_ = "Esperando el móvil…";
    65|        driverAttempted_ = false;
    66|        return;
    67|    }
    68|
    69|    if (serial != deviceSerial_ || state_.load() != State::Connected) {
    70|        deviceSerial_ = serial;
    71|        // Reenvío de puertos: el PC habla con el servidor de sincronización de
    72|        // la app Android a través de adb (sin Wi-Fi, solo USB).
    73|        runAdb("-s " + serial + " forward tcp:" + juce::String(SYNC_PORT)
    74|               + " tcp:" + juce::String(SYNC_PORT));
    75|        state_.store(State::Connected);
    76|        lastInfo_ = "Móvil conectado: " + serial;
    77|        requestSync();
    78|    }
    79|}
