    81|bool PhoneLink::connectAndExchange(const juce::var& send, juce::var& reply) {
    82|    if (deviceSerial_.isEmpty()) return false;
    83|    juce::StreamingSocket socket;
    84|    if (!socket.connect("127.0.0.1", SYNC_PORT, 1500)) return false;
    85|    const auto line = juce::JSON::toString(send, true);
    86|    const auto utf8 = line.toUTF8();
    87|    if (!socket.write(utf8.getAddress(), static_cast<int>(utf8.sizeInBytes() - 1))) {
    88|        socket.close();
    89|        return false;
    90|    }
    91|    char buffer[65536];
    92|    const int n = socket.read(buffer, sizeof(buffer) - 1, false);
    93|    socket.close();
    94|    if (n <= 0) return false;
    95|    buffer[n] = '\0';
    96|    reply = juce::JSON::parse(juce::String::fromUTF8(buffer, n));
    97|    return !reply.isVoid();
    98|}
