   100|bool PhoneLink::pushSync(const juce::var& payload) {
   101|    juce::var reply;
   102|    auto msg = juce::DynamicObject::ObjectMap{};
   103|    auto obj = new juce::DynamicObject();
   104|    obj->setProperty("type", "push");
   105|    obj->setProperty("payload", payload);
   106|    if (!connectAndExchange(juce::var(obj), reply)) {
   107|        state_.store(State::SyncError);
   108|        return false;
   109|    }
   110|    lastInfo_ = "Ajustes enviados al móvil";
   111|    return true;
   112|}
   113|
   114|bool PhoneLink::requestSync() {
   115|    juce::var reply;
   116|    auto obj = new juce::DynamicObject();
   117|    obj->setProperty("type", "pull");
   118|    if (!connectAndExchange(juce::var(obj), reply)) {
   119|        state_.store(State::SyncError);
   120|        lastInfo_ = "Abre Acoustical en el móvil para sincronizar";
   121|        return false;
   122|    }
   123|    lastInfo_ = "Sincronizado con el móvil";
   124|    if (onSync) onSync(reply);
   125|    return true;
   126|}

