     1|// ConsoleComponent.h — consola principal: pestañas EQ / Ruteos / Ajustes /
     2|// Análisis, glue del motor con el dispositivo de audio, generador de señales,
     3|// presets, atajos de teclado y enlace con el móvil.
     4|#pragma once
