   126|private:
   127|    // === Motor / audio ===
   128|
   129|    void toggleEngine() {
   130|        if (engine_.isRunning()) {
   131|            engine_.stop();
   132|            powerButton_.setButtonText("Motor");
   133|        } else {
   134|            engine_.start();
   135|            powerButton_.setButtonText("Parar");
   136|        }
   137|    }
   138|
   139|    void toggleDynamicEq(int index) {
   140|        const bool target = !dynamicEqEnabled_[index];
   141|        engine_.setDynamicEqEnabled(index, target);
   142|        dynamicEqEnabled_[index] = target;
   143|    }
   144|
   145|    void audioDeviceIOCallback(const float** input, int numInputs, float** output,
   146|                               int numOutputs, int numSamples) override {
   147|        std::vector<float> mono(static_cast<size_t>(numSamples), 0.0f);
   148|        for (int ch = 0; ch < numInputs; ++ch)
   149|            if (const auto* in = input[ch])
   150|                for (int s = 0; s < numSamples; ++s) mono[s] += in[s];
   151|
   152|        // Generador de señales → se procesa por el EQ como una entrada más
   153|        if (generatorActive_.load() && numOutputs > 0) {
   154|            generatorBuffer_.assign(static_cast<size_t>(numSamples), 0.0f);
   155|            engine_.signalGenerator().fill(generatorBuffer_.data(), numSamples,
   156|                                           static_cast<float>(lastSampleRate_));
   157|            for (int s = 0; s < numSamples; ++s) mono[s] += generatorBuffer_[s];
   158|        }
   159|
   160|        engine_.pushSamples(mono.data(), numSamples, lastSampleRate_);
   161|
   162|        // Salida: EQ en tiempo real por canal (correcciones de los 3 ecuas)
   163|        std::vector<float> left(static_cast<size_t>(numSamples));
   164|        std::vector<float> right(static_cast<size_t>(numSamples));
   165|        {
   166|            std::lock_guard<std::mutex> lock(dspMutex_);
   167|            std::copy(mono.begin(), mono.end(), left.begin());
   168|            std::copy(mono.begin(), mono.end(), right.begin());
   169|            engine_.eqDspL().process(left.data(), numSamples);
   170|            engine_.eqDspR().process(right.data(), numSamples);
   171|        }
   172|
   173|        if (numOutputs > 0 && output[0])
   174|            std::copy(left.begin(), left.end(), output[0]);
   175|        if (numOutputs > 1 && output[1])
   176|            std::copy(right.begin(), right.end(), output[1]);
   177|        for (int ch = 2; ch < numOutputs; ++ch)
   178|            if (output[ch])
   179|                std::copy(right.begin(), right.end(), output[ch]);
   180|    }
