   205|        EqCanvas::Snapshot snap;
   206|        {
   207|            std::lock_guard<std::mutex> lock(analysisMutex_);
   208|            if (!lastAnalysis_) return;
   209|            snap.bandFrequencies = engine_.bandFrequencies();
   210|            snap.gains = lastAnalysis_->combinedGainsL;
   211|            snap.gainsR = lastAnalysis_->combinedGainsR;
   212|            snap.maxGainDb = std::max(engine_.config().maxGainDb,
   213|                                      acoustical::DynamicEqConfig::MAX_GAIN_DB);
   214|            snap.stereoUnlinked = false;
   215|            for (int i = 0; i < 3; ++i) {
   216|                if (!dynamicEqEnabled_[i]) continue;
   217|                const int b = activeBand_[i];
   218|                if (b >= 0 && b < static_cast<int>(snap.bandFrequencies.size()))
   219|                    snap.highlights[b] = i == 0 ? theme::eq1Cyan
   220|                                       : i == 1 ? theme::eq2Amber : theme::eq3Magenta;
   221|            }
   222|            spectrumView_->updateSpectrum(*lastAnalysis_);
   223|        }
   224|        eqCanvas_->setSnapshot(snap);
   225|
   226|        // 2. Tarjetas de los tres ecuas
   227|        for (int i = 0; i < 3; ++i) {
   228|            DynamicEqCard::Snapshot card;
   229|            card.title = juce::String("Ecu dinámico ") + juce::String(i + 1);
   230|            card.directionLabel = i == 0 ? "Donde más se necesita"
   231|                                : i == 1 ? "Empezando por los graves"
   232|                                         : "Empezando por los agudos";
   233|            card.accent = i == 0 ? theme::eq1Cyan : i == 1 ? theme::eq2Amber : theme::eq3Magenta;
   234|            card.enabled = dynamicEqEnabled_[i];
   235|            card.maxGainDb = engine_.config().maxGainDb;
   236|            {
   237|                std::lock_guard<std::mutex> lock(analysisMutex_);
   238|                if (lastAnalysis_ && lastAnalysis_->dynamicEqGainsL.size() > static_cast<size_t>(i))
   239|                    card.gains = lastAnalysis_->dynamicEqGainsL[i];
   240|            }
   241|            {
   242|                std::lock_guard<std::mutex> lock(sweepMutex_);
   243|                if (sweepSteps_[i].bandIndex >= 0) {
   244|                    card.activeBand = sweepSteps_[i].bandIndex;
   245|                    card.channelBadge = activeChannel_[i];
