bool PhoneLink::httpDownloadToFile(const juce::String& path, const juce::File& dest, int64 maxBytes) {
    juce::StreamingSocket socket;
    if (!socket.connect("127.0.0.1", SYNC_PORT, 3000)) return false;
    const auto req = juce::String("GET ") + path + " HTTP/1.0\r\nHost: phone\r\nConnection: close\r\n\r\n";
    const auto utf8 = req.toUTF8();
    if (!socket.write(utf8.getAddress(), (int)utf8.sizeInBytes() - 1)) { socket.close(); return false; }
    // 1. cabeceras byte a byte/por trozos hasta \r\n\r\n
    juce::MemoryBlock header; // accumulate small
    char buffer[65536];
    int headerEnd = -1;
    juce::MemoryBlock pending;
    while (headerEnd < 0) {
        const int n = socket.read(buffer, sizeof(buffer), false);
        if (n <= 0) break;
        pending.append(buffer, (size_t)n);
        // buscar \r\n\r\n en pending
        const char* p = (const char*)pending.getData();
        const int size = (int)pending.getSize();
        for (int i = 0; i + 3 < size; ++i)
            if (p[i]=='\r'&&p[i+1]=='\n'&&p[i+2]=='\r'&&p[i+3]=='\n') { headerEnd = i; break; }
    }
    if (headerEnd < 0) { socket.close(); return false; }
    const auto headers = juce::String::fromUTF8((const char*)pending.getData(), headerEnd);
    const int status = headers.fromFirstOccurrenceOf(" ", false, false).upToFirstOccurrenceOf(" ", false, false).getIntValue();
    const int64 contentLength = ... parse "Content-Length:" line case-insensitive;
    if (status != 200) { socket.close(); return false; }
    juce::FileOutputStream out(dest);
    if (!out.openedOk()) { socket.close(); return false; }
    // cuerpo ya recibido tras cabeceras
    const char* data = (const char*)pending.getData() + headerEnd + 4;
    const int bodyStart = (int)pending.getSize() - (headerEnd + 4);
    int64 total = bodyStart;
    if (bodyStart > 0) out.write(data, bodyStart);
    int64 limit = maxBytes > 0 ? maxBytes : std::numeric_limits<int64>::max();
    while (total < limit) {
        const int n = socket.read(buffer, sizeof(buffer), false);
        if (n <= 0) break;
        out.write(buffer, n);
        total += n;
    }
    out.flush();
    socket.close();
    return total > 0 && (contentLength <= 0 || total == contentLength);
}
