    @Volatile private var serverThread: Thread? = null

    fun start() {
        if (serverThread?.isAlive == true) return
        val t = Thread({ acceptLoop() }, "acoustical-sync-server")
        t.isDaemon = true
        serverThread = t
        t.start()
    }

    private fun acceptLoop() {
        try {
            ServerSocket(PORT, 4, InetAddress.getByName("127.0.0.1")).use { server ->
                _serverRunning.value = true
                while (!Thread.currentThread().isInterrupted) {
                    val client = try { server.accept() } catch (e: Exception) { break }
                    try { handle(client) } catch (e: Exception) { /* keep serving */ }
                    runCatching { client.close() }
                }
            }
        } catch (e: Exception) {
            _status.value = "Servidor no disponible: ${e.message ?: "error"}"
        } finally {
            _serverRunning.value = false
        }
    }
