    private fun readUpTo(input: java.io.InputStream, buffer: ByteArray): Int {
        var total = 0
        while (total == 0) {
            val n = input.read(buffer, 0, buffer.size)
            if (n < 0) return total
            total += n
        }
        // ya hay al menos un byte; drena lo disponible sin bloquear
        while (total < buffer.size) {
            val n = try { input.read(buffer, total, buffer.size - total) } catch (e: SocketTimeoutException) { break }
            if (n < 0) break
            total += n
        }
        return total
    }
