    private fun manifestJson(): String {
        val file = payloadFile()
        return buildJsonObject {
            put("type", "manifest")
            put("ok", true)
            putJsonObject("app") {
                put("name", "AcoustiCal")
                put("versionCode", BuildConfig.VERSION_CODE)
                put("versionName", BuildConfig.VERSION_NAME)
